userscript.function:

switch (name) {
    case "SAVE":
        doSave();
        break;
    case "REAL_SEAL":
        doRealSave();
        break;
    case "APPROVAL_REQ":
        doApprovalRequest();
        break;
    case "IMPRESS_REQUEST":
        doImpressRequest();
        break;
    case "IMPRESS_ACCEPT":
        if ($APPLY_TYPE == "U" || $APPLY_TYPE == "D") {
            doManagerAccept();
        }
        if ($APPLY_TYPE == "C") {
            doLegalAccept();
        } else
            break;
    case "IMPRESS_REJECT":
        if ($APPLY_TYPE == "U" || $APPLY_TYPE == "D") {
            doManagerReject();
        } else if ($APPLY_TYPE == "C") {
            doLegalReject();
        }
        break;
    case "COMPLETE":
        doComplete();
        break;
    case "BACK":
        doBack();
        break;
    case "DECIDE_REQUEST":
        doDecideRequest();
        break;
    case "DECIDE_ACCEPT":
        doDecideAccept();
        break;
    case "DECIDE_REJECT":
        doDecideReject();
        break;
    case "MANUAL":
    	doDownloadManual();
    	break;
    default:
        break;
}


