    if (screenFlag == 'R') {
        gridObj.setColumnHidden(gridObj.getColIndexById('COUNT'), 1); // 실물일때 필요없음
        if (smrStatus == 'C') {
            gridObj.setColumnHidden(gridObj.getColIndexById('REAL_ATTACH_IMG'), false); // 실물이 완료 됬을때 필요
        }
    } else {
        if (sUtils.workflow.check('SUM1693975008371')) {
            gridObj.setColumnHidden(gridObj.getColIndexById('COUNT'), 0);
        } else {
            gridObj.setColumnHidden(gridObj.getColIndexById('COUNT'), 1);
        }
