                    var manage_no = gridObj.cells(id, gridObj.getColIndexById('MANAGE_NUMBER')).getValue();
                    if (manage_no == "") {
                        seal_choice = false;
                        return;
                    }

                    manage_no_list.push(manage_no);

                    var rowManageNumbers = manage_no.split(','); //
                    AllManageArray.push(rowManageNumbers);
                });


                if (!seal_choice && realFlag == '1') {
                    Alert(Sepoa.cache.text.get('SLM_271.SEAL_CHOICE'));
                    return;
                }
            }

            Confirm(Sepoa.cache.text.get('SLM_271.MESSAGE_APPROVAL_REQUEST'), function(flag) {
                if (flag) {
                    doSave({
                        CALLBACK: doSetApproval,
                        CALLBACK_PARMETER: {
                            APPROVAL_PRC_TYPE: "APPROVAL_REQUEST",
                        }
                    });
                }
            });


        	var params = {};
            params.data = [{
                SEAL_SORT: $APPLY_TYPE,
                APP_LINE_SEQ: '0',
                APP_METHOD: '01',
                APP_USER_ID: Sepoa.info.ID,
                APP_USER_NAME: Sepoa.info.NAME_LOC,
                SELLER_CODE: Sepoa.info.COMPANY_CODE,
                POSITION: Sepoa.info.POSITION,
                DEPARTMENT_NAME: Sepoa.info.DEPARTMENT_NAME_LOC,
                DEPT: Sepoa.info.DEPARTMENT,
                EMPLOYEE_NO: Sepoa.info.EMPLOYEE_NO,
                MANAGE_NO_LIST: manage_no_list
            }];

            let MANAGER_NUMBER = [];

            for (var i = 0; i<gridObj.getRowsNum(); i++) {
            	MANAGER_NUMBER.push(gridObj._getRowData(gridObj.getRowId(i)).MANAGE_NUMBER);
            }

            doServiceAjax('sepoa.svc.seal.SepoaReqSealService', 'CONNECTION', 'doSelectInitAppLine', {
                HOUSE_CODE: Sepoa.info.HOUSE_CODE,
                COMPANY_CODE: Sepoa.info.COMPANY_CODE,
                CTRL_CODE: 'REQ_SEAL_Affairs',
                USE_NUMBER: formObj.getValue('SEAL_USE_TYPE'),
                MANAGER_NUMBER: MANAGER_NUMBER
            }, function(so) {
                if (so.status == 1) {
                    var sf = new SepoaFormater(so.result[0]);
                    var sfList = sf.getArrayMap();
                    let cnt = 0;

                    for (let i=0; i<sfList.length; i++) {

                    	let approver = sfList[i];
                    	let isExist = null;

                    	// 같은 ID가 있는지 확인
                    	params.data.forEach(item => {
						    if(item.APP_USER_ID == approver.APP_USER_ID) isExist = true; 
						});

						if(isExist) continue;

                    	cnt++;
                        approver.APP_LINE_SEQ = String(cnt);
                        approver.APP_METHOD = '04';
                        approver.NOT_CHANGE = true;
                        params.data.push(approver);
                    }
                    // 결재선 목록 결재순서 내림차순 정렬
                    params.data.sort(function (a,b) {
						return b.APP_LINE_SEQ - a.APP_LINE_SEQ;
					});
                } else {
                    Alert("초기 결재자 세팅에 실패하였습니다.")
                }
            }, false);

            var width = Math.min(SUX.root.innerWidth * 0.7, 1280);
            var height = Math.min((SUX.root.innerHeight - 100) * 0.9, 800);
            PopupOpenPost('/UxDefault/ApprovalLine/Popup.sux', params, function(data) {
                var params = {};
                params.data = data;
                params.callbackParams = callbackParams;

                doApprovalProcess(params);
            }, width, height, Sepoa.cache.text.get('SLM_221.APPLINE_SETTING'));


        	var linkFlag = false;
        	if (!sUtils.string.isBlank(Sepoa.request.isPopup) && Sepoa.request.isPopup == 'true') { // 링크 접속일 경우, 결재요청 후 창 자동 종료
				linkFlag = true;                    		
        	}
            var config = {
                url: window.CONTEXT_NAME + '/SepoaActionController.sux',
                on: {
                    callback: function(res) {
                        if (res.status == "1") {
                            if(linkFlag){
                            	doWindowClose(Sepoa.cache.text.get('MESSAGE.0001'));
                            } else {
                                Alert(Sepoa.cache.text.get('MESSAGE.0001'));
                                if (Sepoa.request.SMR_NUMBER) {
                                    doQuery(Sepoa.request.SMR_NUMBER);
                                } else if (smrStatus == 'T' && moveFlag == 'Y') {
                                    linkTo('SLM_280', '/Seal/Document/Request/SealDocumentSummaryLayout.sux', 'undefined', Sepoa.cache.text.get('SLM_221.REQUEST_LIST'));
                                    SUX.root.getContentsCell(window).close();
                                } else {
                                    doBack();
                                }
                            }
                        } else {
                            if(linkFlag){ 
                            	doWindowClose(res.message);
                            } else{
                            	Alert(res.message);
                            }
                        }
                    }
                }
            }

            if ($APPLY_TYPE == "D") {
                var attachDocArr = new Array();
                gridObj2.forEachRowA(function(id) {
                    var attachDocData = {};
                    attachDocData.SD_NUMBER = gridObj2.cells(id, gridObj2.getColIndexById('SD_NUMBER')).getValue();
                    attachDocData.SMI_NUMBER = gridObj2.cells(id, gridObj2.getColIndexById('SMI_NUMBER')).getValue();
                    attachDocData.COUNT = String(gridObj2.cells(id, gridObj2.getColIndexById('COUNT')).getValue());
                    attachDocData.CONTENTS = gridObj2.cells(id, gridObj2.getColIndexById('CONTENTS')).getValue();
                    attachDocData.REAL_DOC_CHK = gridObj2.cells(id, gridObj2.getColIndexById('REAL_DOC_CHK')).getValue();

                    attachDocArr.push(attachDocData);
                });
                $documentList = attachDocArr;
            }

            var serviceData = {
                REQ_SEAL_INFO: $reqSealInfo,
                DOCUMENT_LIST: $documentList,
                APP_LINE: params.data.approver,
                APP_INFO: {
                    APP_COMMENT: params.data.comment
                }
            };

            var params = {
                module: "seal" + (Sepoa.config.get('sepoa.seal.process') || "") + ".req",
                action: "doRequestService",
                CONNECTION: "TRANSACTION",
                CURRENT_PRC: "APPROVAL",
                PARAMETER: JSON.stringify(serviceData)
            }

            sUtils.multipart.send(config, params);


        	if(message){
	            Alert(message, function(result) {
	                if (result) {
	                    top.window.close();
	                }
	            });
            }


