if (header == "ATTACH_IMG") {
    if (sUtils.workflow.check('STIF1686537827571')) {
        let rowData = gridObj2.getRowDataObject(id);

        if (rowData["REAL_DOC_CHK"] == "R") {
            Alert("실물 교부 서류는 지정된 부서에서 수령하세요.");
            return;
        } else {
            let smrNumber = $reqSealInfo.SMR_NUMBER;
            let key = smrNumber + "_" + rowData["SD_NUMBER"];

            //기존 문서가 있을 경우
            var docData = {
                KEY: key,
                TARGET: "CONVERT_CERT_MERGE#CONVERT_CERT_ORG"
            };

            var btnConfigArr = [];
            btnConfigArr.push("DOWNLOAD");
            btnConfigArr.push("IN");
            btnConfigArr.push("OUT");
            btnConfigArr.push("CLOSE");

            $popup = sUtils.popup.modal({
                url: window.CONTEXT_NAME + '/Contract/Module/SealModuleLayout.sux',
                params: {
                    DOC_DATA: JSON.stringify(docData),
                    CONT_MODULE: "VIEW",
                    WORK_TYPE: "T",
                    CALLER: "ATTACH_DOC_TEMPLATE",
                    BTN_CONFIG: btnConfigArr
                },
                title: rowData["SUBJECT"]
            });
            resizePopup();
            return;

        }
    } else {
        var confirm_val = false;
        if (gridObj2.cells(id, gridObj2.getColIndexById("REAL_DOC_CHK")).getValue() == '1' ||
            (gridObj2.cells(id, gridObj2.getColIndexById("ATTACH_SEQ")).getValue() == '' &&
                Sepoa.info.CTRL_CODE.indexOf('ATTACH_CONFIRM') < 0)) {
            return false;
        } else if (Sepoa.info.CTRL_CODE.indexOf('ATTACH_CONFIRM') > -1
            //&& gridObj2.cells(id, gridObj2.getColIndexById("ATTACH_SEQ")).getValue() == ''
        ) {
            confirm_val = true;
        }

        var attachNo = gridObj2.cells(id, gridObj2.getColIndexById("ATTACH_NO")).getValue();
        callVaultPopup(attachNo, confirm_val, selectedGridId);
    }
} else if (header == "SEARCH_SMI") {
    if (smrStatus == "T") {
        dataOutput.setValue("ROWID", id);
        let width = Math.min(SUX.root.innerWidth * 0.4, 1280);
   		let height = Math.min((SUX.root.innerHeight - 100) * 0.7, 800);
        PopupOpenPost('/Seal/Document/Common/Popup/SealDocumentCertPopupLayout.sux', null, CertPopupCallback, width, height, Sepoa.cache.text.get('SLM_211_4.SEARCH_SMI'));
    }
} else if (header == "TEMPLATE_DATA") {
    let rowData = gridObj2.getRowDataObject(id);
    rowData['ROW_NUM'] = id;
    rowData['SMR_STATUS'] = smrStatus;
    if (rowData["REAL_DOC_CHK"] == "R") {
        Alert(Sepoa.cache.text.get("SLM_251.NOT_REAL_DOC_TEMPLATE"));
        return;
    }

    if (rowData["SMI_NUMBER"] == "" || rowData["SMI_NUMBER"] == null) {
        Alert(Sepoa.cache.text.get("SLM_221.MSG_0029"));
        return;
    }

    if (rowData["TEMPLATE_FORM"] == "" || rowData["TEMPLATE_FORM"] == null) {
        Alert(Sepoa.cache.text.get("SLM_251.NOT_EXIST_TEMPLATE"));
        return;
    }

    let width = Math.min(SUX.root.innerWidth * 0.3, 1280);
    let height = Math.min((SUX.root.innerHeight - 100) * 0.5, 800);
    PopupOpenPost('/Seal/Document/Cert/Popup/SealDocumentCertTemplateDataMappingPopup.sux', rowData, templateMappingDataCallback, width, height, Sepoa.cache.text.get('SLM_211_4.TEMPLATE_DATA'));
}


let rId = dataOutput.getValue("ROWID");
let reFlag = data.REAL_DOC_FLAG == '1' ? 'R' : 'E';

gridObj2.cells(rId, gridObj2.getColIndexById('SUBJECT')).setValue(data.SUBJECT);
gridObj2.cells(rId, gridObj2.getColIndexById('SMI_NUMBER')).setValue(data.SMI_NUMBER);
gridObj2.cells(rId, gridObj2.getColIndexById('REAL_DOC_CHK')).setValue(reFlag);
gridObj2.cells(rId, gridObj2.getColIndexById('TEMPLATE_FORM')).setValue(data.TEMPLATE_FORM);


var header = this.getColumnId(cInd);
if (stage == 2) { // 값이 변경됬을때
    if (header == 'COUNT') { // 헤더 값이 COUNT일때(셀아이디가 파일첨부일때)
        if (!Number.isSafeInteger(Number(nValue))) { // COUNT셀의 값이 숫자가 아닐때 
            Alert(Sepoa.cache.text.get("SLM_221.MSG_0041")); // 경고창
            return false;
        } else if (Number.isSafeInteger(Number(nValue))) { // COUNT셀의 값이 숫자일때
            if (nValue <= 0) { // 0보다 작을경우
                Alert(Sepoa.cache.text.get("SLM_221.MSG_0041")); // 경고창 
                return false;
            }
        }
        gridObj.cells(rId, gridObj.getColIndexById(header)).setValue(nValue);
    } else {
        gridObj.cells(rId, gridObj.getColIndexById(header)).setValue(nValue);
    }
}
return true;


var header = gridObj2.getColumnId(cInd);
var chk_disable = gridObj2.cells(rId, gridObj2.getColIndexById('REAL_DOC_CHK')).isDisabled();

if ($APPLY_TYPE == "D") {
    if (stage == 2 && header == "REAL_DOC_CHK") {
        if (nValue == "R") {
            gridObj2.cells(rId, gridObj2.getColIndexById('COUNT')).setValue(0);
        }
    }
}

if (stage == 0 && header == "REAL_DOC_CHK" && chk_disable == true) {
    return false;
}

if (stage == 0 && header == "COUNT") {
    let reFlag = gridObj2.cells(rId, gridObj2.getColIndexById('REAL_DOC_CHK')).getValue();
    if (!reFlag || reFlag == "" || reFlag == "R") {
        Alert("전자 교부서류만 부수 지정이 가능합니다.")
        return;
    }
}

return true;


if (e.fileCount > 0) {
    gridObj2.cells(param.rId, gridObj2.getColIndexById('ATTACH_IMG')).setIcon('ATTACH_IMG2');
    gridObj2.cells(param.rId, gridObj2.getColIndexById('ATTACH_IMG')).cell.children[0].style = 'filter:none';
} else {
    gridObj2.cells(param.rId, gridObj2.getColIndexById('ATTACH_IMG')).setIcon('ATTACH_IMG');
    gridObj2.cells(param.rId, gridObj2.getColIndexById('ATTACH_IMG')).cell.children[0].style = 'filter:none';
}

