doServiceAjax('sepoa.svc.seal.SepoaReqSealService', 'CONNECTION', 'doCorpDocInfo', {
    SMI_NUMBER: smi_no
}, function(so) {
    if (so.status == 1) {
        var sf = new SepoaFormater(so.result[0]);
        var sfList = sf.getArrayMap();

        if (sf.getRowCount() > 0) {
            var ListResult = sfList[0];
            let reFlag = ListResult.REAL_DOC_FLAG == '1' ? 'R' : 'E';

            gridObj2.cells(rId, gridObj2.getColIndexById('SUBJECT')).setValue(ListResult.SUBJECT);
            gridObj2.cells(rId, gridObj2.getColIndexById('SMI_NUMBER')).setValue(ListResult.SMI_NUMBER);
            gridObj2.cells(rId, gridObj2.getColIndexById('REAL_DOC_CHK')).setValue(reFlag);
        }
    } else {
        Alert(Sepoa.cache.text.get("MESSAGE.MISSING_DOC"));
    }
});


var type = '';

if ($APPLY_TYPE == "D") {
    var type = "smi_doc";
} else {
    type = 'TODO_DOC';
}

var mode = confirm_val == true ? '' : 'VI';
vaultPopup({
