Confirm(Sepoa.cache.text.get('SLM_221.DECIDE_REQUEST_REJECT'), function(flag) {
    if (flag) {
        doSave({
            CALLBACK: doDecideProcess,
            CALLBACK_PARMETER: {
                LEGAL_PRC_TYPE: "DECIDE_REJECT"
            }
