});


var smrNumber = $reqSealInfo.SMR_NUMBER;
var checkReject = false;
doServiceAjax('sepoa.svc.seal.SepoaReqSealService', 'CONNECTION', 'doCheckDecide', {
    SMR_NUMBER: smrNumber,
    HOUSE_CODE: Sepoa.info.HOUSE_CODE,
    COMPANY_CODE: Sepoa.info.COMPANY_CODE
}, function(so) {
    if (so.status == 1) {
        if (so.result[0] == "true") {
            checkReject = true;
        } else {
            checkReject = false;
        }
    } else {
        Alert(Sepoa.cache.text.get("MESSAGE.1002")); //오류발생
        return false;
    }
}, false);

return checkReject;


var config = {
    url: window.CONTEXT_NAME + '/SepoaActionController.sux',
    on: {
        callback: function(res) {
            if (res.status == "1") {
                Alert(Sepoa.cache.text.get('MESSAGE.0001'));
                if (Sepoa.request.SMR_NUMBER) { //이미 SMR_NUMBER값이 있었다면
                    doQuery(Sepoa.request.SMR_NUMBER);
                } else if (smrStatus == 'T' && moveFlag == 'Y') { //새로 만든 요청이라면 
                    linkTo('SLM_280', '/Seal/Document/Request/SealDocumentSummaryLayout.sux', 'undefined', Sepoa.cache.text.get('SLM_221.REQUEST_LIST'));
                    SUX.root.getContentsCell(window).close();
                } else {
                    doBack();
                }
            } else {
                Alert(res.message);
            }
        }
    }
}

